6. Add the command handler to your main file:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');
const { ban } = require('./commands');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.commands = new Map();
client.commands.set(ban.name, ban);

// ...

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

// ...
```

7. Implement the `execute` method for the `ban` command in `commands.js`:

```javascript
const { ApplicationCommandType, ApplicationCommandOptionType } = require('discord.js');

module.exports = {
  name: 'ban',
  type: ApplicationCommandType.ChatInput,
  description: 'Bans a user from the server',
  options: [
    {
      name: 'user',
      type: ApplicationCommandOptionType.User,
      description: 'The user to ban',
      required: true,
    },
    {
      name: 'reason',
      type: ApplicationCommandOptionType.String,
      description: 'The reason for the ban',
      required: false,
    },
  ],

  async execute(interaction) {
    const { member, options } = interaction;

    const user = options.getUser('user');
    const reason = options.getString('reason', true);

    // Ban the user
    await member.guild.ban(user.id, { days: 7, reason: reason });

    await interaction.reply(`Successfully banned ${user.tag} for ${reason || 'no reason'}.`);
  },
