    {"***", "</code></pre><hr>"},
    {"_", "<sub>"},
    {"^", "<sup>"},
    {"\\", "<br>"}
};

std::string convertMarkdownToHTML(std::string& markdown) {
    std::string html;

    // Iterate over each character in the input string
    for (char c : markdown) {
        bool is_open_tag = false;

        // Check if the current character is the beginning of a Markdown tag
        for (const auto& [markdown_tag, html_tag] : markdown_to_html_tags) {
            if (markdown.find(markdown_tag) != std::string::npos && !is_open_tag) {
                // If a Markdown tag is found, replace it with the corresponding HTML tag
                html += html_tag;
                is_open_tag = true;
            } else if (html.find(html_tag) != std::string::npos && is_open_tag) {
                // If the HTML tag is found, close the previous tag
                html.pop_back();
                is_open_tag = false;
            }
        }

        // Append the current character to the HTML string
        if (!is_open_tag) {
            html += c;
        }
    }

    return html;
}

